# ============================================================
# AEGIS NIDS - STEP 9: Policy Engine Integration
# ============================================================
# Wires PolicyEngine + PEP with the full detection pipeline:
#   - buildPolicyContext(): derives DEFCON, threat_intel, correlation_count
#   - evaluateAndEnforce(): PolicyEngine.evaluate() + PEP.enforce()
#   - processEventFullPipeline(): combined pipeline:
#       RAG -> flow -> detection -> correlation -> policy -> PEP
#   - 3 default rules loaded at startup (block critical, alert high, log low)
#   - registerRule()/setDefaultAction() for runtime policy updates
#
# Blueprint principle: "Policy decides, PEP executes, neither both"
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 9 - Policy Engine Integration"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step9_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/policy_integration.zig (policy_integration.zig, 747 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/policy_integration.zig" -ExpectedLines 747 -Base64Content $B64_1
Write-Host ""

# File 2: core/rag_integration.zig (rag_integration.zig, 720 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/rag_integration.zig" -ExpectedLines 720 -Base64Content $B64_2
Write-Host ""

# File 3: core/nids_analyze.zig (nids_analyze.zig, 2340 lines)
$B64_3 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2340 -Base64Content $B64_3
Write-Host ""

# File 4: core/nids_main.zig (nids_main.zig, 275 lines)
$B64_4 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 275 -Base64Content $B64_4
Write-Host ""

# File 5: build.zig (build.zig, 88 lines)
$B64_5 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 88 -Base64Content $B64_5
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

